TWComponent.script:
if(!!tw.local.results){

   for(var i=0;i<tw.local.results[0].rows.listLength;i++){
       for(var j=0 ; j< tw.local.transaction.listLength; j++){
        /*if( tw.local.results[0].rows[i].data[1] == tw.local.transaction[j].referenceNumber
        	&& tw.local.results[0].rows[i].data[0] == tw.local.transaction[j].accountNo){*/
        
        if(  tw.local.results[0].rows[i].data[0] == tw.local.transaction[j].accountNo
        	&&  tw.local.results[0].rows[i].data[3].getDay() == tw.local.transaction[j].postingDate.getDay()
        	&& tw.local.results[0].rows[i].data[3].getMonth() == tw.local.transaction[j].postingDate.getMonth()
        	&& tw.local.results[0].rows[i].data[3].getFullYear() == tw.local.transaction[j].postingDate.getFullYear()
        ){
        	
               tw.local.transaction[j].existAmount = tw.local.results[0].rows[i].data[2];
             
             if(tw.local.transaction[j].existAmount == tw.local.transaction[j].transactionAmount)
                   tw.local.transaction.removeIndex(j);
               //    break;
               }
           }
       } 
}

var unique = new tw.object.listOf.MWFCTransactions();
tw.local.transaction = new tw.object.listOf.FCTransactions();

if (tw.local.MWtransactions != null && tw.local.MWtransactions.listLength != 0) {
    for (var i = 0; i < tw.local.MWtransactions.listLength; i++) {
        var isDuplicate = false; 


        for (var j = 0; j < unique.listLength; j++) {

            if (
                unique[j].referenceNumber == tw.local.MWtransactions[i].referenceNumber &&
                unique[j].postingDate.getFullYear() == tw.local.MWtransactions[i].postingDate.getFullYear() &&
                unique[j].postingDate.getMonth() == tw.local.MWtransactions[i].postingDate.getMonth() &&
                unique[j].postingDate.getDate() == tw.local.MWtransactions[i].postingDate.getDate()
            ) {
                isDuplicate = true; 
                break;
            }
        }

        if (!isDuplicate) {
            var newUniqueTransaction = new tw.object.MWFCTransactions();
            newUniqueTransaction = tw.local.MWtransactions[i];
            unique[unique.listLength] = newUniqueTransaction;

            var newTransaction = new tw.object.FCTransactions();
            newTransaction.referenceNumber = tw.local.MWtransactions[i].referenceNumber;
            newTransaction.accountNo = tw.local.MWtransactions[i].accountNumber;
            newTransaction.valueDate = tw.local.MWtransactions[i].valueDate;
            newTransaction.postingDate = tw.local.MWtransactions[i].postingDate;
            newTransaction.transactionAmount = tw.local.MWtransactions[i].transactionAmount;

            tw.local.transaction[tw.local.transaction.listLength] = newTransaction;
        }
    }
}

//tw.local.testTrans = new tw.object.listOf.FCTransactions();
tw.local.testJson = tw.local.MWtransactions.toJSONString(true);

//for (var i=0; i<tw.local.transaction.listLength; i++) {
//	if(tw.local.transaction[i].referenceNumber == "176LGPB213220001"){
//		tw.local.transaction.insertIntoList(tw.local.transaction.listLength, tw.local.transaction[i])
//	}
//}

/*var amend = "" + tw.epv.RequestType.Amendment;
var recreate = "" + tw.epv.RequestType.Recreate;
var create = "" + tw.epv.RequestType.Create;
var completed = "" + tw.epv.Status.completed; 
var final = "" +tw.epv.RequestState.Final;*/

//tw.local.sql ="SELECT tr.TRANSACTIONREFNO, tr.AMOUNTLINKEDINBPM FROM "+ tw.env.DBSchema +".ODC_FCTRANSACTION tr Inner join  "+ tw.env.DBSchema +".ODC_REQUESTINFO req on CAST(req.id  AS varchar(25))= tr.REQUESRID where tr.ACCOUNTNO = ? and req.id = (SELECT max(id) FROM "+ tw.env.DBSchema +".ODC_REQUESTINFO WHERE ( REQUESTTYPE = '"+amend+"' OR REQUESTTYPE = '"+recreate+"' OR REQUESTTYPE = '"+create+"') AND REQUESTSTATE = '"+final+"'  AND REQUESTSTATUS='"+completed+"' ) ;";
tw.local.sqlStat = new tw.object.listOf.SQLStatement();


for(var i = 0 ; i<tw.local.transaction.listLength;i++){
tw.local.sqlStat[i] = new tw.object.SQLStatement();
tw.local.sqlStat[i].sql ="SELECT ACCOUNTNO, TRANSACTIONREFNO, AMOUNTLINKEDINBPM,POSTINGDATE FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION WHERE TRANSACTIONREFNO = ? AND ACCOUNTNO = ? ORDER BY ID DESC FETCH FIRST 1 ROW ONLY;"
tw.local.sqlStat[i].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStat[i].parameters[0] =  new tw.object.SQLParameter();
tw.local.sqlStat[i].parameters[1] =  new tw.object.SQLParameter();
tw.local.sqlStat[i].parameters[0].value = tw.local.transaction[i].referenceNumber;
tw.local.sqlStat[i].parameters[1].value = tw.local.transaction[i].accountNo;

}

