    for (var i = 0; i < tw.local.MWtransactions.listLength; i++) {
        var isDuplicate = false; 


        for (var j = 0; j < unique.listLength; j++) {

            if (
                unique[j].referenceNumber == tw.local.MWtransactions[i].referenceNumber &&
                unique[j].postingDate.getFullYear() == tw.local.MWtransactions[i].postingDate.getFullYear() &&
                unique[j].postingDate.getMonth() == tw.local.MWtransactions[i].postingDate.getMonth() &&
                unique[j].postingDate.getDate() == tw.local.MWtransactions[i].postingDate.getDate()
            ) {
                isDuplicate = true; 
                break;
            }
        }

        if (!isDuplicate) {
            var newUniqueTransaction = new tw.object.MWFCTransactions();
            newUniqueTransaction = tw.local.MWtransactions[i];
            unique[unique.listLength] = newUniqueTransaction;

            var newTransaction = new tw.object.FCTransactions();
            newTransaction.referenceNumber = tw.local.MWtransactions[i].referenceNumber;
            newTransaction.accountNo = tw.local.MWtransactions[i].accountNumber;
            newTransaction.valueDate = tw.local.MWtransactions[i].valueDate;
            newTransaction.postingDate = tw.local.MWtransactions[i].postingDate;
            newTransaction.transactionAmount = tw.local.MWtransactions[i].transactionAmount;

            tw.local.transaction[tw.local.transaction.listLength] = newTransaction;
        }
    }
}

